package com.aiexcel.platform.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

/**
 * A single business analysis recommendation generated by the AI.
 * The AI decides which analyses are useful; the backend never executes them.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class AnalysisRecommendation {

    /** Concise, human-readable title of the recommended analysis */
    private String title;

    /** Short description of what the analysis would reveal and why it matters */
    private String description;

    /** Category of analysis (e.g., TREND, COMPARISON, DISTRIBUTION, CORRELATION, ANOMALY, SEGMENTATION, SUMMARY) */
    private String analysisType;

    /** Sheet names that this analysis would draw from */
    private List<String> relevantSheets;

    /** Column names that this analysis would focus on (across the relevant sheets) */
    private List<String> relevantColumns;

    /** Plain-language explanation of the business value of running this analysis */
    private String businessValue;
}
